#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
vector<int> adj[MAXN];
bool visited[MAXN];
int dist[MAXN];

// Поиск в глубину (DFS)
void dfs(int u, int p = -1) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (v != p && !visited[v]) {
            dfs(v, u);
        }
    }
}

// Поиск в ширину (BFS)
void bfs(int start) {
    memset(dist, -1, sizeof(dist));
    queue<int> q;
    q.push(start);
    dist[start] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    int n, m; // n - вершины, m - ребра
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u); // Для неориентированного графа
    }

    dfs(1);
    bfs(1);

    return 0;
}
